 "Der Plan und seine Sessions im Kalender werden entfernt. Deine bisherigen Lernsessions bleiben.": "Il piano e le sue sessioni nel calendario verranno rimossi. Le tue sessioni di studio precedenti rimangono.",
 "Deutsch (Duden erlaubt): Textverständnis eines Sachtexts, Grammatik und Sprachbetrachtung (Satzglieder, Konjunktiv, indirekte Rede, Kommaregeln) und ein Aufsatz/argumentativer Text.": "Tedesco (Duden consentito): comprensione di un testo informativo, grammatica e analisi linguistica (funzioni della frase, congiuntivo, discorso indiretto, regole di punteggiatura) e un saggio/testo argomentativo.",
 "Deutsch BMP: Erörterung/Interpretation zu einem literarischen oder pragmatischen Text, Textanalyse, Sprachreflexion.": "Tedesco BMP: discussione/interpretazione di un testo letterario o pragmatico, analisi del testo, riflessione linguistica.",
 "Deutsch Matura: Aufsatz (Erörterung, Interpretation eines Gedichts/Prosatexts, Essay) – Aufgaben mit Textbezug und Begründung.": "Matura tedesco: Saggio (discussione, interpretazione di una poesia/testo in prosa, essay) – compiti con riferimento al testo e motivazione.",
