 "Bringe die Schritte in die richtige Reihenfolge, wie sie im Text beschrieben sind.": "Metti i passaggi nell’ordine corretto, come descritti nel testo.",
 "Bringe die Schritte in die richtige Reihenfolge.": "Metti i passaggi nell’ordine corretto.",
