 "Coenzym": "Coenzima",
 "Dabei wird": "In questo processo",
 "Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert.": "Viene rilasciata energia e una parte viene immagazzinata in ATP.",
 "Dabei wird ein Molekül Glucose mit sechs Kohlenstoffatomen in zwei Moleküle Pyruvat mit je drei Kohlenstoffatomen gespalten. Der übrig bleibende Rest mit zwei Kohlenstoffatomen verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "Una molecola di glucosio a sei atomi di carbonio si divide in due molecole di piruvato da tre atomi ciascuna. Il resto di due atomi di carbonio si combina con il coenzima A formando acetil‑CoA.",
 "Danke dir! Jetzt bist du dran mit den Fragen.": "Grazie! Ora tocca a te con le domande.",
 "Danke für deine Erklärung.": "Grazie per la spiegazione.",
 "Das": "Il",
 "Das Bild konnte nicht geladen werden.": "Impossibile caricare l’immagine.",
 "Das Material dieses Kurses fehlt auf diesem Gerät – bitte neu hochladen.": "Il materiale di questo corso non è presente su questo dispositivo – per favore caricalo di nuovo.",
 "Das Pyruvat gelangt nun aus dem Zellplasma in die ____, die man oft als Kraftwerke der Zelle bezeichnet. Der übrig bleibende Rest mit zwei ____ verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "Il piruvato passa ora dal citoplasma cellulare nella ____, spesso chiamata centrale energetica della cellula. Il residuo rimasto si combina con due ____ e con il coenzima A per formare l’acetil‑CoA.",
 "Das Wichtigste": "Il più importante",
 "Das ____ ist die Eintrittsstelle für den nächsten Abschnitt. Sauerstoff wird in diesem Abschnitt noch nicht verbraucht, doch der Zyklus steht still, wenn die ____ keinen Sauerstoff erhält.": "Il ____ è il punto d’ingresso per la sezione successiva. L’ossigeno non viene ancora consumato qui, ma il ciclo si ferma se le ____ non ricevono ossigeno.",
 "Das ____ und das ____.": "Il ____ e il ____.",
 "Das dauert einen Moment. Du kannst die App offen lassen.": "Ci vuole un attimo. Puoi tenere l’app aperta.",
 "Das erste Wort steht dafür, dass dem Pyruvat Wasserstoff entzogen wird, das zweite dafür, dass eine Carboxylgruppe als Kohlenstoffdioxid abgespalten wird. Dabei werden zwei Moleküle Kohlenstoffdioxid abgespalten, und am Ende des Kreislaufs steht wieder Oxalacetat bereit, sodass der Zyklus von vorn beginnen kann.": "La prima parola indica la rimozione di idrogeno dal piruvato, la seconda la perdita di una carbossilica come CO₂. Vengono rilasciate due molecole di CO₂ e alla fine del ciclo l’ossalacetato è di nuovo pronto, così il ciclo può ricominciare.",
 "Das grosse Ziel wartet": "Il grande obiettivo ti aspetta",
 "Das hat nicht geklappt": "Non ha funzionato",
 "Das sitzt noch nicht": "Non è ancora pronto",
