 "Deine Unterlagen bleiben auf deinem Gerät.": "I tuoi documenti rimarranno sul tuo dispositivo.",
 "Deine bisherigen Antworten gehen verloren und der Versuch wird nicht gezählt.": "Le risposte precedenti andranno perse e il tentativo non verrà conteggiato.",
 "Demo – ohne KI": "Demo – senza IA",
 "Demo – ohne KI.": "Demo – senza IA.",
 "Demo – ohne KI. Die Prüfung ist ein Beispiel; Kurzantworten und Aufsätze können nicht richtig korrigiert werden.": "Demo – senza IA. L’esame è un esempio; risposte brevi e saggi non possono essere corretti correttamente.",
 "Demo-Bewertung ohne KI (nur Länge und Schlüsselwörter): # Wörter. Eine inhaltliche Beurteilung gibt es nur mit der KI-Verbindung.": "Valutazione demo senza IA (solo lunghezza e parole‑chiave): # parole. Una valutazione di contenuto è disponibile solo con la connessione IA.",
 "Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung.": "La degradazione graduale del glucosio con ossigeno si chiama respirazione cellulare.",
 "Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man ….": "La degradazione graduale del glucosio con ossigeno si chiama ….",
 "Denk kurz nach, dann dreh die Karte um.": "Rifletti un attimo, poi gira la carta.",
 "Der Abbruch läuft noch, einen Moment.": "L’interruzione è ancora in corso, un attimo.",
 "Der Aufbau wurde unterbrochen.": "La costruzione è stata interrotta.",
 "Der Citratzyklus in der Matrix": "Il ciclo di Krebs nella matrice",
 "Der Citratzyklus in der Matrix: # Prozent": "Il ciclo di Krebs nella matrice: # %​",
 "Der Citratzyklus läuft ebenfalls in der Matrix der ____ ab. Weil aus einer Glucose zwei ____ entstehen, läuft der Zyklus pro Glucose zweimal.": "Il ciclo di Krebs avviene anche nella matrice della ____. Poiché da un glucosio nascono due ____, il ciclo si ripete due volte per glucosio.",
 "Der Kurs und dein Fortschritt gehen verloren. Deine Originaldateien auf dem Gerät werden auch entfernt.": "Il corso e i tuoi progressi andranno persi. I file originali sul dispositivo verranno rimossi.",
 "Der Text ist noch zu kurz. Füge mehr Notizen ein oder lade eine Datei hoch.": "Il testo è ancora troppo corto. Aggiungi più note o carica un file.",
 "Der eingefügte Text ist zu lang (höchstens ca. 150 Seiten). Lade ihn als Datei hoch oder kürze ihn.": "Il testo inserito è troppo lungo (max circa 150 pagine). Caricalo come file o accorcialo.",
 "Der wichtigste Brennstoff vieler Zellen ist die Glucose, also der Traubenzucker. Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung. Sie liefert den grössten Teil des ATP in tierischen und pflanzlichen Zellen. Man kann die Zellatmung in einer einzigen Gleichung zusammenfassen.": "Il combustibile più importante di molte cellule è il glucosio, lo zucchero d’uva. La degradazione graduale del glucosio con ossigeno si chiama respirazione cellulare. Fornisce la maggior parte dell’ATP nelle cellule animali e vegetali. Si può riassumere la respirazione cellulare in un’unica equazione.",
 "Deshalb muss sie ATP laufend neu herstellen, indem sie energiereiche": "Perciò deve continuamente rigenerare ATP, usando energia ricca",
 "Deutsch (Schweizer Rechtschreibung, kein ß)": "Tedesco (ortografia svizzera, senza ß)",
 "Deutsch · Prüfung Do, #. Oktober · noch # Tage": "Tedesco · Esame Gi, # ottobre · ancora # giorni",
 "Deutsch: Stimme «Thorsten» (Thorsten Müller, Datensatz Thorsten-Voice «high», CC0).": "Tedesco: voce «Thorsten» (Thorsten Müller, dataset Thorsten‑Voice «high», CC0).",
 "Deutschland: bestanden bis Note #": "Germania: superato con voto #",
 "Di #:#": "Di #:#",
 "Die Atmungskette an der inneren Membran": "La catena respiratoria sulla membrana interna",
 "Die Atmungskette an der inneren Membran: # Prozent": "La catena respiratoria sulla membrana interna: # %​",
 "Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "La catena respiratoria è formata da diversi complessi proteici, attraverso i quali gli elettroni vengono trasferiti come su una scala.",
 "Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden. Am Ende der Kette nimmt Sauerstoff die Elektronen und Protonen auf und bildet damit Wasser. Wenn kein Sauerstoff vorhanden ist, kann die Zelle die Atmungskette nicht betreiben.": "La catena respiratoria è formata da diversi complessi proteici, attraverso i quali gli elettroni vengono trasferiti come su una scala. Alla fine della catena l’ossigeno accetta elettroni e protoni formando acqua. Senza ossigeno la cellula non può usare la catena.",
 "Die Bewertung hat gerade nicht geklappt. Dein Text ist noch da – versuche es nochmal.": "La valutazione non è riuscita. Il tuo testo è ancora qui – riprova.",
 "Die Bewertung hat gerade nicht geklappt. Deine Antwort ist noch da – versuche es nochmal.": "La valutazione non è riuscita. La tua risposta è ancora qui – riprova.",
 "Die Bewertung ist in dieser Version noch nicht verfügbar.": "La valutazione non è ancora disponibile in questa versione.",
 "Die Bewertung war unbrauchbar. Bitte nochmals versuchen.": "La valutazione era inutilizzabile. Per favore riprova.",
 "Die Korrektur der offenen Antworten hat nicht geklappt. Deine Antworten sind noch da – bitte versuche es nochmals.": "La correzione delle risposte aperte non è riuscita. Le tue risposte sono ancora qui – riprova.",
 "Die Mitochondrien besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "I mitocondri sono composti da diversi complessi proteici, attraverso i quali gli elettroni vengono trasferiti come su una scala.",
 "Die Muskelzellen besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "Le cellule muscolari sono composte da diversi complessi proteici, attraverso i quali gli elettroni vengono trasferiti come su una scala.",
 "Die Protonen fliessen durch das Enzym ____ zurück in die Matrix. Fehlt der ____, staut sich die Kette zurück, und die Zelle kann kaum noch ATP auf diesem Weg herstellen.": "I protoni fluiscono attraverso l’enzima ____ di nuovo nella matrice. Se manca il ____, la catena si intasa e la cellula produce pochissimo ATP via questo percorso.",
 "Die Prüfung deckt nicht alle Konzepte ab:": "L’esame non copre tutti i concetti:",
 "Die Prüfung enthält zu wenige Aufgaben:": "L’esame contiene troppo pochi compiti:",
 "Die Prüfung konnte nicht erstellt werden. Bitte versuche es nochmals.": "L’esame non può essere creato. Per favore riprova.",
 "Die Prüfung wartet am Ende": "L’esame ti aspetta alla fine",
 "Die Sprachausgabe funktioniert gerade nicht.": "La sintesi vocale non funziona al momento.",
 "Die Unterlagen sind nicht mehr im Speicher. Bitte lade sie noch einmal hoch.": "I documenti non sono più in memoria. Per favore ricaricali.",
 "Die Wiedergabe stoppt, wenn du die App in den Hintergrund legst oder den Bildschirm sperrst. Mit «Weiter» geht es am Satz weiter, wo du aufgehört hast.": "La riproduzione si ferma se metti l’app in background o blocchi lo schermo. Con «Continua» riprendi dalla frase dove ti eri fermato.",
 "Die Überträger besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "Il trasportatore è composto da più complessi proteici, che trasferiscono gli elettroni come su gradini di una scala.",
 "Diese Form ist das Molekül ATP, die Abkürzung für": "Questa forma è la molecola ATP, l’abbreviazione di",
 "Diese Form ist das Molekül ATP, die Abkürzung für Adenosintriphosphat.": "Questa forma è la molecola ATP, l’abbreviazione di Adenosintrifosfato.",
