 "Eddy (Deutsch (Deutschland))": "Eddy (Deutsch (Deutschland))",
 "Eigener Text": "Testo personalizzato",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Decarboxylierung und sechs Molekülen Wasser.": "Una molecola di glucosio reagisce con sei molecole di ossigeno formando sei molecole di decarbossilazione e sei molecole di acqua.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Intermembranraum und sechs Molekülen Wasser.": "Una molecola di glucosio reagisce con sei molecole di ossigeno formando sei molecole di spazio intermembrana e sei molecole di acqua.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Kohlenstoffdioxid und sechs Molekülen Wasser.": "Una molecola di glucosio reagisce con sei molecole di ossigeno formando sei molecole di anidride carbonica e sei molecole di acqua.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Kohlenstoffdioxid und sechs Molekülen Wasser. Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert. Der Rest geht als Wärme verloren, was erklärt, warum unser Körper warm bleibt. In Wirklichkeit läuft die Zellatmung nicht in einem Schritt ab.": "Una molecola di glucosio reagisce con sei molecole di ossigeno formando sei molecole di anidride carbonica e sei molecole di acqua. Viene rilasciata energia, parte della quale è immagazzinata in ATP. Il resto si disperde come calore, spiegando perché il nostro corpo rimane caldo. In realtà la respirazione cellulare non avviene in un unico passo.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Stoffwechselweg und sechs Molekülen Wasser.": "Una molecola di glucosio reagisce con sei molecole di ossigeno formando sei molecole di percorso metabolico e sei molecole di acqua.",
 "Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen … und sechs Molekülen Wasser.": "Una molecola di glucosio reagisce con sei molecole di ossigeno formando sei molecole di … e sei molecole di acqua.",
 "Eine Erklär-Aufgabe": "Compito di spiegazione",
 "Eine Seite oder ein Foto konnte nicht aufbereitet werden.": "Una pagina o una foto non può essere elaborata.",
