 "Ergänze: «Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen ___ und sechs Molekülen Wasser.»": "Completa: «Una molecola di glucosio reagisce con sei molecole di ossigeno formando sei molecole di ___ e sei molecole di acqua.»",
 "Ergänze: «Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative ___, der Citratzyklus und die Atmungskette.»": "Completa: «Invece la cellula scompone lo zucchero in quattro fasi consecutive: glicolisi, ___ ossidativa, ciclo di citrato e catena respiratoria.»",
 "Ergänze: «Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitt…": "Completa: «Invece la cellula scompone lo zucchero in quattro fasi consecutive…",
 "Ergänze: «Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird ___ frei, die die Zelle für ihre Arbeit nutzen kann.»": "Completa: «Quando un gruppo fosfato viene rimosso dall’ATP, si forma ADP e viene rilasciato ___, che la cellula può usare per il suo lavoro.»",
 "Ergänze: «Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird…": "Completa: «Quando un gruppo fosfato viene rimosso dall’ATP, si forma ADP e viene rilasciato…",
 "Erklär es Brainy": "Spiegalo a Brainy",
 "Erkläre ausführlich und mit den wichtigsten Begriffen: «": "Spiega in modo dettagliato e con i termini chiave: «",
 "Erkläre ausführlich und mit den wichtigsten Begriffen: «Die Atmungskette an der inneren Membran».": "Spiega in modo dettagliato e con i termini chiave: «La catena respiratoria nella membrana interna».",
 "Erkläre es bitte in ein, zwei Sätzen.": "Spiegalo per favore in una o due frasi.",
 "Erkläre es so einfach, wie du kannst …": "Spiegalo nel modo più semplice possibile …",
