 "Im Material wurde kein verwertbarer Text gefunden.": "Nel materiale non è stato trovato testo utilizzabile.",
 "In den Dateien wurde kein lesbarer Text gefunden.": "Nei file non è stato trovato testo leggibile.",
 "In den Unterlagen wurde kein lesbarer Text gefunden. Versuche schärfere Fotos oder eine andere Datei.": "Nel materiale non è stato trovato testo leggibile. Prova foto più nitide o un altro file.",
 "In dieser Lektion sind alle Bausteine abgewählt. Schalte im Strategy Room Lernmethoden ein.": "In questa lezione tutti i blocchi sono disattivati. Attiva i metodi di apprendimento nella Strategy Room.",
 "In eigenen Worten, von Brainy bewertet": "In parole tue, valutato da Brainy",
 "In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und Kohlenstoffdioxid.": "Nei nostri muscoli si forma acido lattico, nei lieviti etanolo e anidride carbonica.",
 "Jede lebende Zelle muss ständig arbeiten.": "Ogni cellula vivente deve lavorare continuamente.",
 "Jede lebende Zelle muss ständig arbeiten. Sie baut Eiweisse auf, transportiert Stoffe durch ihre Membran, teilt sich und hält ihre Struktur aufrecht. Für alle diese Vorgänge benötigt sie Energie in einer Form, die sofort verfügbar ist. Diese Form ist das Molekül ATP, die Abkürzung für Adenosintriphosphat.": "Ogni cellula vivente deve lavorare continuamente. Costruisce proteine, trasporta sostanze attraverso la membrana, si divide e mantiene la sua struttura. Per tutti questi processi serve energia immediatamente disponibile: la molecola ATP, abbreviazione di Adenosintrifosfato.",
 "Jeden Schritt eingeben und prüfen": "Inserisci ogni passo e controlla",
 "Jetzt abgeben": "Consegna ora",
 "Jetzt wartet deine Prüfung": "Ora ti aspetta l’esame",
 "Jetzt wird deine Prüfung aus deinem Material erstellt.": "Ora il tuo esame viene creato dal tuo materiale.",
 "Kannst du «": "Puoi «",
 "Kannst du «Adenosintriphosphat» in einem Satz erklären? Dann sitzt der Kern.": "Puoi spiegare «Adenosintriphosphat» in una frase? Allora il nucleo è pronto.",
