 "Keine Antwort.": "Nessuna risposta.",
 "Keine Antwort. Richtig wäre: A) Dabei wird ein Molekül Glucose mit sechs Kohlenstoffatomen in zwei Moleküle Pyruvat mit je drei Kohlenstoffatomen gespalten.": "Nessuna risposta. La risposta corretta sarebbe: A) Una molecola di glucosio con sei atomi di carbonio si divide in due molecole di piruvato con tre atomi di carbonio ciascuna.",
 "Keine Antwort. Richtig wäre: A) a": "Nessuna risposta. La risposta corretta sarebbe: A) a",
 "Keine Antwort. Richtig wäre: B) Sauerstoff": "Nessuna risposta. La risposta corretta sarebbe: B) Ossigeno",
 "Keine Antwort. Richtig wäre: C) c": "Nessuna risposta. La risposta corretta sarebbe: C) c",
 "Keine Antwort. Richtig wäre: D) Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "Nessuna risposta. La risposta corretta sarebbe: D) L'anidride carbonica che espiriamo proviene quindi dalla decarbossilazione ossidativa e dal ciclo del citrato.",
 "Keine Antwort. Richtig wäre: D) Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen weitergereicht werden.": "Nessuna risposta. La risposta corretta sarebbe: D) La catena respiratoria è composta da diversi complessi proteici, attraverso i quali gli elettroni vengono trasferiti come su gradini di una scala.",
 "Keine Antwort. Richtig wäre: D) Ein Molekül Glucose reagiert mit sechs Molekülen Sauerstoff zu sechs Molekülen Kohlenstoffdioxid und sechs Molekülen Wasser.": "Nessuna risposta. La risposta corretta sarebbe: D) Una molecola di glucosio reagisce con sei molecole di ossigeno per formare sei molecole di anidride carbonica e sei molecole di acqua.",
 "Keine Antwort. Richtig wäre: D) Energie": "Nessuna risposta. La risposta corretta sarebbe: D) Energia",
