 "Richtig: «Zellatmung» – so steht es im Text.": "Corretto: «Respirazione cellulare» – così è nel testo.",
 "Richtige Reihenfolge": "Ordine corretto",
 "Richtige Reihenfolge: #. Diese Membran ist stark gefaltet, die Falten heissen Cristae. · #. Die frei werdende Energie wird genutzt, um Protonen aus der Matrix in den Intermembranraum zu pumpen. · #. Sauerstoff ist also der letzte Elektronenakzeptor. · #. Wenn kein Sauerstoff vorhanden ist, kann die Zelle die Atmungskette nicht betreiben.": "Ordine corretto: #. Questa membrana è molto piegata, le pieghe si chiamano Cristae. · #. L'energia rilasciata viene usata per pompare protoni dalla matrice allo spazio intermembrana. · #. L'ossigeno è quindi l'ultimo accettore di elettroni. · #. Se non c'è ossigeno, la cellula non può far funzionare la catena respiratoria.",
 "Richtige Reihenfolge: #. Dieser Schritt heisst oxidative Decarboxylierung. · #. Zuerst verbindet sich das Acetyl-CoA mit dem Molekül Oxalacetat zu Citrat, das Citrat hat sechs Kohlenstoffatome. · #. Weil aus einer Glucose zwei Acetyl-CoA entstehen, läuft der Zyklus pro Glucose zweimal. · #. Die Atmungskette sitzt in der inneren Membran der Mitochondrien.": "Ordine corretto: #. Questo passo si chiama decarbossilazione ossidativa. · #. Prima l'Acetil-CoA si combina con l'ossalacetato formando citrato, che ha sei atomi di carbonio. · #. Poiché da una glucosio nascono due Acetil-CoA, il ciclo avviene due volte per glucosio. · #. La catena respiratoria si trova nella membrana interna dei mitocondri.",
 "Richtige Reihenfolge: #. Jede lebende Zelle muss ständig arbeiten. · #. ATP wirkt wie eine kleine, aufladbare Batterie der Zelle. · #. Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung. · #. Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert.": "Ordine corretto: #. Ogni cellula viva deve lavorare continuamente. · #. L'ATP funziona come una piccola batteria ricaricabile della cellula. · #. La degradazione graduale del glucosio con ossigeno si chiama respirazione cellulare. · #. Viene rilasciata energia, parte della quale viene immagazzinata in ATP.",
 "Richtige Reihenfolge: #. So wird die Energie in kleinen Portionen frei und kann gezielt in ATP umgewandelt werden. · #. Zuerst muss die Zelle selbst zwei ATP einsetzen, um die Glucose zu aktivieren. · #. Die Glykolyse braucht keinen Sauerstoff. · #. Der übrig bleibende Rest mit zwei Kohlenstoffatomen verbindet sich mit dem Coenzym A zum Acetyl-CoA.": "Ordine corretto: #. L'energia viene rilasciata in piccole porzioni e può essere convertita in ATP. · #. Prima la cellula usa due ATP per attivare il glucosio. · #. La glicolisi non richiede ossigeno. · #. Il residuo a due carboni si combina con il coenzima A formando Acetil-CoA.",
 "Richtige Reihenfolge: #. erst · #. dann · #. danach · #. zuletzt": "Ordine corretto: #. prima · #. poi · #. dopo · #. infine",
