 "Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Decarboxylierung, der Citratzyklus und die Atmungskette.": "Invece la cellula scompone lo zucchero in quattro fasi consecutive: glicolisi, decarbossilazione ossidativa, ciclo del citrato e catena respiratoria.",
