 "Würde die Glucose auf einmal verbrennen, entstünde ein Wärmeblitz, den die Zelle nicht nutzen könnte.": "Se il glucosio bruciasse tutto in una volta, si creerebbe un lampo di calore inutilizzabile dalla cellula.",
 "Würde die Glucose auf einmal verbrennen, entstünde ein Wärmeblitz, den die Zelle nicht nutzen könnte. Stattdessen zerlegt die Zelle den Zucker in vier aufeinanderfolgenden Abschnitten: die Glykolyse, die oxidative Decarboxylierung, der Citratzyklus und die Atmungskette. So wird die Energie in kleinen Portionen frei und kann gezielt in ATP umgewandelt werden.": "Se il glucosio bruciasse tutto in una volta, si creerebbe un lampo di calore inutilizzabile. Invece la cellula scompone lo zucchero in quattro fasi: glicolisi, decarbossilazione ossidativa, ciclo di citrato e catena respiratoria. L'energia viene rilasciata a piccoli tratti e trasformata in ATP.",
