 "«Am Ende der Kette nimmt Sauerstoff die Elektronen und Protonen auf und bildet damit Wasser.» ist richtig; «In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und Stoffwechselweg.» ist falsch; «Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird Energie frei, die die Zelle für ihre Arbeit nutzen kann.» ist richtig.": "«Alla fine della catena l'ossigeno cattura elettroni e protoni formando acqua.» è corretto; «Nelle nostre cellule muscolari si forma acido lattico, nelle cellule di lievito etanolo e percorso metabolico.» è errato; «Quando un gruppo fosfato si stacca dall'ATP, si forma ADP e si libera energia che la cellula usa per il lavoro.» è corretto.",
 "«Aussage eins» ist richtig; «Aussage zwei» ist falsch.": "«Affermare uno» è corretto; «Affermare due» è errato.",
 "«Aussage zwei» ist falsch.": "«Affermare due» è errato.",
