 "«Oxalacetat» passt hier nicht; im Text steht an dieser Stelle «Zellatmung».": "«Ossalacetato» non è adatto; nel testo c'è «Respirazione cellulare».",
 "«Zellatmung (Beispiel)» löschen?": "Eliminare «Respirazione cellulare (esempio)»?",
 "«Zusätzlich» passt hier nicht; im Text steht an dieser Stelle «Zellatmung».": "«In più» non è adatto; nel testo c'è «Respirazione cellulare».",
