 "#. ATP wirkt wie eine kleine, aufladbare Batterie der Zelle.": "#. L'ATP funziona come una piccola batteria ricaricabile della cellula.",
 "#. Dabei wird Energie freigesetzt, und ein Teil davon wird in ATP gespeichert.": "#. Viene rilasciata energia, e una parte di essa viene immagazzinata in ATP.",
 "#. Den schrittweisen Abbau der Glucose unter Verwendung von Sauerstoff nennt man Zellatmung.": "#. La degradazione graduale del glucosio usando ossigeno si chiama respirazione cellulare.",
 "#. Jede lebende Zelle muss ständig arbeiten.": "#. Ogni cellula vivente deve lavorare costantemente.",
