 "Alles richtig.": "Tutto corretto.",
 "Am Ende der Kette nimmt Sauerstoff die Elektronen und Protonen auf und bildet damit Wasser. Sauerstoff ist also der letzte Elektronenakzeptor.": "Alla fine della catena l'ossigeno prende gli elettroni e i protoni formando acqua. L'ossigeno è quindi l'ultimo accettore di elettroni.",
 "Anders als in den Lektionen läuft hier die Zeit. Der Countdown ist immer sichtbar, bei Zeitablauf wird automatisch abgegeben. Du kannst frei zwischen den Fragen springen.": "Diversamente dalle lezioni, qui il tempo scorre. Il conto alla rovescia è sempre visibile, al termine il test viene inviato automaticamente. Puoi saltare liberamente tra le domande.",
