 "Die Transferfragen konnten nicht sauber erstellt werden:": "Le domande di trasferimento non sono state create correttamente:",
 "ATP wirkt wie eine kleine, aufladbare Batterie der Zelle. Wenn eine Phosphatgruppe von ATP abgespalten wird, entsteht ADP, und dabei wird Energie frei, die die Zelle für ihre Arbeit nutzen kann. Die Zelle kann ATP nicht in grossen Mengen lagern. Deshalb muss sie ATP laufend neu herstellen, indem sie energiereiche Nährstoffe abbaut.": "L'ATP funziona come una piccola batteria ricaricabile della cellula. Quando un gruppo fosfato viene rimosso dall'ATP, si forma ADP e viene rilasciata energia che la cellula può usare per il suo lavoro. La cellula non può immagazzinare grandi quantità di ATP. Perciò deve produrlo continuamente, degradando nutrienti ricchi di energia.",
