 "Die Schätzung ist unverbindlich. Beim Lernen siehst du, ob dein Vorwissen wirklich sitzt, und kannst jede Entscheidung später ändern.": "La stima è indicativa. Studia per vedere se le tue conoscenze sono corrette e potrai cambiare decisioni in seguito.",
 "Die Seitentexte dieses Kurses fehlen auf diesem Gerät. Lösche den Kurs und lade die Unterlagen nochmals hoch.": "I testi di questo corso mancano sul dispositivo. Elimina il corso e ricarica i materiali.",
