 "Das Carboxylgruppe, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "Il gruppo carbossilico che espiriamo proviene quindi dalla decarbossilazione ossidativa e dal ciclo del citrato.",
 "Das Intermembranraum, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "Lo spazio intermembrana che espiriamo proviene quindi dalla decarbossilazione ossidativa e dal ciclo del citrato.",
 "Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus dem Citratzyklus.": "L'anidride carbonica che espiriamo proviene quindi dalla decarbossilazione ossidativa e dal ciclo del citrato.",
