 "Der Citratzyklus in der Matrix · # % richtig": "Il ciclo del citrato nella matrice · # % corretto",
 "Der Citratzyklus in der Matrix · ca. # Min. · das dauert nur einen Moment.": "Il ciclo del citrato nella matrice · ca. # min. · dura solo un attimo.",
 "Der Citratzyklus in der Matrix, Läuft. Etappe öffnen": "Il ciclo del citrato nella matrice, In corso. Apri fase",
 "Der Citratzyklus in der Matrix, Offen. Etappe öffnen": "Il ciclo del citrato nella matrice, Aperto. Apri fase",
 "Der Druck gibt an, wie stark eine Kraft auf eine": "La pressione indica quanto è forte una forza su una",
 "Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck. Der Druck ist der Quotient aus Kraft und Fläche.": "La pressione indica quanto è forte una forza su una superficie specifica. La stessa forza su una piccola area genera alta pressione, su una grande area bassa pressione. La pressione è il quoziente tra forza e area.",
 "Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck. Deshalb sinkt man mit Schuhen im Schnee tiefer ein als mit breiten Skiern. Der Druck ist der Quotient aus Kraft und Fläche.": "La pressione indica quanto è forte una forza su una superficie specifica. La stessa forza su una piccola area genera alta pressione, su una grande area bassa pressione. Per questo con scarpe nella neve si affonda più in profondità rispetto a sci larghi. La pressione è il quoziente tra forza e area.",
 "Falsch: Im Basistext steht «Mitochondrium», nicht «Stoffwechsel».": "Sbagliato: nel testo di base c’è «Mitochondrio», non «Metabolismo».",
