 "Felix Wagner": "Felix Wagner",
 "Fettsäuren werden in Stücke mit je zwei Intermembranraum zerlegt, die als Acetyl-CoA direkt in den Citratzyklus eintreten.": "Gli acidi grassi vengono divisi in segmenti di due spazi intermembrana, che entrano come Acetil-CoA direttamente nel ciclo di Krebs.",
 "Fettsäuren werden in Stücke mit je zwei Kohlenstoffatomen zerlegt, die als Acetyl-CoA direkt in den Citratzyklus eintreten.": "Gli acidi grassi vengono divisi in segmenti di due atomi di carbonio, che entrano come Acetil-CoA direttamente nel ciclo di Krebs.",
 "Fettsäuren werden in Stücke mit je zwei Kohlenstoffatomen zerlegt, die als Acetyl-CoA direkt in den…": "Gli acidi grassi vengono divisi in segmenti di due atomi di carbonio, che entrano come Acetil-CoA direttamente nel…",
 "Fettsäuren werden in Stücke mit je zwei Stoffwechselweg zerlegt, die als Acetyl-CoA direkt in den Citratzyklus eintreten.": "Gli acidi grassi vengono divisi in segmenti di due vie metaboliche, che entrano come Acetil-CoA direttamente nel ciclo di Krebs.",
 "Fettsäuren werden in Stücke mit je zwei Wasserstoffatome zerlegt, die als Acetyl-CoA direkt in den Citratzyklus eintreten.": "Gli acidi grassi vengono divisi in segmenti di due atomi di idrogeno, che entrano come Acetil-CoA direttamente nel ciclo di Krebs.",
