 "Im Alltag gibt man sie meistens in … pro Stunde an, in der Physik rechnet man häufig mit Metern pro Sekunde.": "Nella vita quotidiana le indichi solitamente in … all'ora, in fisica si usa spesso metri al secondo.",
 "In": "In",
 "In der Physik wird Arbeit verrichtet, wenn eine Kraft einen Körper über eine Strecke bewegt.": "In fisica si compie lavoro quando una forza sposta un corpo su una distanza.",
 "In der Physik wird Arbeit verrichtet, wenn eine Kraft einen Körper über eine Strecke bewegt. Wer eine Kiste nur festhält, ohne sie zu bewegen, verrichtet im physikalischen Sinn keine Arbeit. Die Arbeit ist umso grösser, je grösser die Kraft und je länger der Weg ist. Gemessen wird sie in Joule.": "In fisica si compie lavoro quando una forza sposta un corpo su una distanza. Tenere una cassa ferma non è lavoro. Il lavoro aumenta con forza e distanza. Si misura in Joule.",
 "In der Physik wird Arbeit …, wenn eine Kraft einen Körper über eine Strecke bewegt.": "In fisica il lavoro … quando una forza sposta un corpo.",
 "In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und…": "Nei nostri muscoli nasce acido lattico, nei lieviti etanolo e…",
 "Intermembranraum": "Spazio intermembrana",
