 "Je": "Je",
 "Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern. Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck. Der Druck ist der Quotient aus Kraft und Fläche.": "Più è grande la massa, più forza serve per cambiare la velocità. La pressione indica la forza per unità di area. Stessa forza su area piccola = alta pressione, su area grande = bassa pressione. Pressione = forza/area.",
 "Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern. Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche einen kleinen Druck.": "Più è grande la massa, più forza serve per cambiare la velocità. Stessa forza su area piccola = alta pressione, su area grande = bassa pressione.",
 "Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Kilometer zu ändern.": "Più è grande la massa, più forza serve per cambiare i chilometri.",
 "Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Kilometern zu ändern.": "Più è grande la massa, più forza serve per cambiare i chilometri.",
