 "Siehe Basistext: Abschnitt # «Der Citratzyklus in der Matrix» – «Das Kohlenstoffdioxid, das wir ausatmen, stammt also aus der oxidativen Decarboxylierung und aus»": "Vedi testo di base: sezione # «Il ciclo del citrato nella matrice» – «L'anidride carbonica che espiriamo proviene quindi dalla decarbossilazione ossidativa e da»",
 "Siehe Basistext: Abschnitt # «Der Citratzyklus in der Matrix» – «Sauerstoff wird in diesem Abschnitt noch nicht verbraucht, doch der Zyklus steht still, wenn die»": "Vedi testo di base: sezione # «Il ciclo del citrato nella matrice» – «L'ossigeno non è ancora consumato in questa sezione, ma il ciclo si ferma se la»",
 "Siehe Basistext: Abschnitt # «Dichte» – «Die Dichte beschreibt, wie viel Masse in einem bestimmten Volumen steckt.»": "Vedi testo di base: sezione # «Densità» – «La densità descrive quanta massa è contenuta in un certo volume.»",
 "Siehe Basistext: Abschnitt # «Die Atmungskette an der inneren Membran» – «Die Atmungskette besteht aus mehreren Proteinkomplexen, durch die Elektronen wie über Treppenstufen»": "Vedi testo di base: sezione # «La catena respiratoria nella membrana interna» – «La catena respiratoria è composta da diversi complessi proteici, attraverso i quali gli elettroni scendono come su una scala»",
 "Siehe Basistext: Abschnitt # «Druck» – «$p = \\frac{F}{A}$ (p: Druck, F: Kraft, A: Fläche)»": "Vedi testo di base: sezione # «Pressione» – «$p = \\frac{F}{A}$ (p: pressione, F: forza, A: area)»",
 "Siehe Basistext: Abschnitt # «Druck» – «Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt.»": "Vedi testo di base: sezione # «Pressione» – «La pressione indica quanto è forte una forza su una certa area.»",
 "Siehe Basistext: Abschnitt # «Druck» – «Der Druck ist der Quotient aus Kraft und Fläche.»": "Vedi testo di base: sezione # «Pressione» – «La pressione è il quoziente tra forza e area.»",
 "Siehe Basistext: Abschnitt # «Druck» – «Dieselbe Kraft erzeugt auf einer kleinen Fläche einen grossen Druck und auf einer grossen Fläche»": "Vedi testo di base: sezione # «Pressione» – «La stessa forza genera alta pressione su una piccola area e bassa pressione su una grande area»",
 "Siehe Basistext: Abschnitt # «Energie und Glucose im Überblick» – «Die Energie verbindet die Protein und hängt eng mit der Stoffwechsel und dem Energie zusammen, weil»": "Vedi testo di base: sezione # «Energia e glucosio in sintesi» – «L'energia collega le proteine e è strettamente legata al metabolismo e all'energia perché»",
 "Siehe Basistext: Abschnitt # «Energie und Glucose im Überblick» – «Die Mitochondrium verbindet die Chromosom und hängt eng mit der Zelle und dem Chromosom zusammen,»": "Vedi testo di base: sezione # «Energia e glucosio in sintesi» – «Il mitocondrio collega i cromosomi e è strettamente legato alla cellula e al cromosoma,»",
 "Siehe Basistext: Abschnitt # «Geschwindigkeit» – «$v = \\frac{s}{t}$ (v: Geschwindigkeit, s: Strecke, t: Zeit)»": "Vedi testo di base: sezione # «Velocità» – «$v = \\frac{s}{t}$ (v: velocità, s: distanza, t: tempo)»",
 "Siehe Basistext: Abschnitt # «Geschwindigkeit» – «Die Geschwindigkeit sagt, wie schnell sich ein Körper bewegt.»": "Vedi testo di base: sezione # «Velocità» – «La velocità indica quanto velocemente si muove un corpo.»",
 "Siehe Basistext: Abschnitt # «Kohlenstoffdioxid» – «Bei Aminosäuren wird zuerst die Aminogruppe abgespalten, der Rest tritt an verschiedenen Stellen in»": "Vedi testo di base: sezione # «Anidride carbonica» – «Nelle amminoacidi prima si rimuove il gruppo amminico, il resto entra in vari punti in»",
 "Siehe Basistext: Abschnitt # «Kohlenstoffdioxid» – «Fettsäuren werden in Stücke mit je zwei Kohlenstoffatomen zerlegt, die als Acetyl-CoA direkt in den»": "Vedi testo di base: sezione # «Anidride carbonica» – «Gli acidi grassi sono suddivisi in pezzi di due atomi di carbonio, che come Acetil-CoA entrano direttamente nel»",
 "Siehe Basistext: Abschnitt # «Kohlenstoffdioxid» – «In unseren Muskelzellen entsteht auf diese Weise Milchsäure, in Hefezellen entstehen Ethanol und»": "Vedi testo di base: sezione # «Anidride carbonica» – «Nelle nostre cellule muscolari si forma acido lattico, nelle cellule di lievito si forma etanolo e»",
 "Siehe Basistext: Abschnitt # «Kraft» – «Ein Newton beschleunigt eine Masse von einem Kilogramm in jeder Sekunde um einen Meter pro Sekunde.»": "Vedi testo di base: sezione # «Forza» – «Un Newton accelera una massa di un chilogrammo di un metro al secondo ogni secondo.»",
 "Siehe Basistext: Abschnitt # «Kraft» – «Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu»": "Vedi testo di base: sezione # «Forza» – «Più grande è la massa di un corpo, più forza serve per modificare la sua velocità.»",
 "Siehe Basistext: Abschnitt # «Membran und Gen im Überblick» – «Die Ribosom liefert die Allel und hängt eng mit der Stoffwechsel und dem Vererbung zusammen, weil»": "Vedi testo di base: sezione # «Membrana e gene in sintesi» – «Il ribosoma fornisce l'allele e è strettamente legato al metabolismo e all'ereditarietà perché»",
 "Siehe Basistext: Abschnitt # «Membran und Gen im Überblick» – «Die Stoffwechsel baut ab die Muskel und hängt eng mit der Chromosom und dem Ribosom zusammen, weil»": "Vedi testo di base: sezione # «Membrana e gene in sintesi» – «Il metabolismo degrada il muscolo e è strettamente legato al cromosoma e al ribosoma perché»",
