 "✓ Richtig: Der Druck gibt an, wie stark eine Kraft auf eine bestimmte Fläche wirkt.": "✓ Giusto: La pressione indica quanto è forte una forza su una certa superficie.",
 "✓ Richtig: Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern.": "✓ Giusto: Più è grande la massa di un corpo, più forza serve per cambiare la sua velocità.",
