 "Eine Kraft kann einen Körper beschleunigen, abbremsen oder verformen. Je grösser die Masse eines Körpers ist, desto mehr Kraft braucht man, um seine Geschwindigkeit zu ändern. Die Einheit der Kraft ist das Newton. Ein Newton beschleunigt eine Masse von einem Kilogramm in jeder Sekunde um einen Meter pro Sekunde.": "Una forza può accelerare, frenare o deformare un corpo. Più è grande la massa di un corpo, più forza serve per cambiare la sua velocità. L'unità di forza è il Newton. Un Newton accelera una massa di un chilogrammo di un metro al secondo ogni secondo.",
