 "Achte besonders auf diese Aussage: Die Energie verbindet die Protein und hängt eng mit der Stoffwechsel und dem Energie zusammen, weil Abschnitt # dies in Schritt # zeigt.": "Fai particolare attenzione a questa affermazione: l'energia collega le proteine e è strettamente legata al metabolismo e all'energia, perché la sezione # lo mostra nel passo #.",
 "Der Druck ist der": "La pressione è la",
 "Der Druck ist der Quotient aus Kraft und Alltag.": "La pressione è il quoziente tra forza e vita quotidiana.",
 "Der Druck ist der Quotient aus Kraft und Arbeit.": "La pressione è il quoziente tra forza e lavoro.",
 "Der Druck ist der Quotient aus Kraft und Fläche.": "La pressione è il quoziente tra forza e superficie.",
