 "Der Name braucht mindestens # Zeichen.": "Il nome deve contenere almeno # caratteri.",
 "Deshalb sinkt man mit … im Schnee tiefer ein als mit breiten Skiern.": "Perciò si affonda più in profondità nella neve con … rispetto a sci larghi.",
 "Diamant I": "Diamante I",
